    if n == 0: return 1
    A = [row[:] for row in A]
    sign = 1
    prev = 1
    for k in range(n-1):
        if A[k][k] == 0:
            # find swap
            for i in range(k+1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    sign = -sign
                    break
            else:
                return 0
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j]*A[k][k] - A[i][k]*A[k][j]) // prev
            A[i][k] = 0
        prev = A[k][k]
    return sign * A[n-1][n-1]

