    """Simplify an absolute Unix path.
    Split the path by '/', use a stack to process components.
    '.' and empty components are ignored. '..' pops the stack if possible.
    Finally, join the stack with '/' and prepend a leading slash.
    """
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, stay at root (ignore)
        else:
            stack.append(part)
    # Build the simplified path
    return '/' + '/'.join(stack) if stack else '/'
